// Источник: web-тест .qa/e2e/tests/prayer-mode/pm-02-same-content-shacharit-ashkenaz.spec.ts, план .qa/e2e/specs/prayer-mode.md, кейс .qa/tests/prayer-mode/PM-02-same-content-both-modes.md
// Тикеты #6a86f7e7, #6a86f7df (6a86f7df6f29…). Опора: F-103 AC1 (до הכרעה minyan-vs-yachid — без различий) · S-17 AC4.
// Текст секции = все тексты элементов на экране (getPageSource), сравнение попарно в «יחיד» и «מניין». «סיים תפילה» не нажимается.
import { expect, $, driver } from '@wdio/globals';
import { byText, byTextMatches, byLabelStartsWith, tapText, expectVisibleText, pageCounter } from '../../helpers/ui.ts';
import { openPrayer, openRoute, hasDeepLinks, goToPage } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';

const KEY = 'shacharit_ashkenaz';
const TITLE = 'שחרית';
const TOTAL = 66;
const SFARAD = KEY.endsWith('_sfarad');

function radio(name: string) {
  return driver.isAndroid
    ? $(`//*[@checkable="true" and (@content-desc="${name}" or .//*[@text="${name}"])]`)
    : $(`-ios predicate string:label == "${name}" OR name == "${name}"`);
}
async function isChecked(name: string) {
  const el = await radio(name);
  if (driver.isAndroid) return (await el.getAttribute('checked')) === 'true';
  const v = await el.getAttribute('value');
  return v === '1' || v === 'checked' || (await el.isSelected());
}
async function select(name: string, other: string) {
  await (await radio(name)).click();
  await driver.waitUntil(async () => (await isChecked(name)) && !(await isChecked(other)), { timeoutMsg: `Не выбран «${name}»` });
}

/** Тексты всех элементов экрана (Android — text, iOS — label) из дерева элементов. */
async function screenTexts(): Promise<string[]> {
  const src = await driver.getPageSource();
  const attr = driver.isAndroid ? 'text' : 'label';
  const decode = (s: string) => s.replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&#10;/g, '\n').replace(/&amp;/g, '&');
  return [...src.matchAll(new RegExp(`\\s${attr}="([^"]*)"`, 'g'))].map((m) => decode(m[1])).filter(Boolean);
}

async function counterIs(expected: string) {
  await driver.waitUntil(async () => (await pageCounter()) === expected, { timeoutMsg: `Счётчик не стал «${expected}»` });
}

/** Пройти «המשך» от 1 до TOTAL, записывая тексты экрана; на каждой секции есть «סיים תפילה», нет пометок «только במניין». */
async function walk(): Promise<string[]> {
  const result: string[] = [];
  for (let i = 1; i <= TOTAL; i++) {
    await counterIs(`${i} מתוך ${TOTAL}`);
    const texts = await screenTexts();
    result.push(texts.join('\n'));
    await expect(byText('סיים תפילה')).toBeDisplayed();
    for (const t of texts) {
      expect(/נאמר רק במניין|יחיד מדלג/.test(t)).toBe(false);
      expect(/(^|\n)חזרת הש״ץ/.test(t)).toBe(false);   // нет отдельной секции «חזרת הש״ץ»
    }
    if (i < TOTAL) await tapText('המשך');
    else await expect(byText('המשך')).not.toBeDisplayed();
  }
  return result;
}

async function switchNusach(to: 'ספרדי' | 'אשכנזי') {
  await (await byLabelStartsWith('בחירת נוסח')).click();
  await tapText(to);
  const replace = await byText('החלף');
  if (await replace.isDisplayed().catch(() => false)) await replace.click();
  await expectVisibleText(`${TITLE} (${to})`);
}

describe('Режим молитвы «יחיד / מניין»', () => {
  afterEach(async () => { await toHome(); });

  it(`PM-02 Содержание и счётчик одинаковы в «יחיד» и «מניין» — ${KEY} #6a86f7e7 #6a86f7df @prod-safe`, async function () {
    this.timeout(2400000);
    // 1. Открыть молитву (ספרד — deep link или смена нусаха в меню); «קודם» до «1 מתוך N».
    if (hasDeepLinks()) await openRoute(`/prayer/${KEY}`);
    else {
      await openPrayer(KEY.replace('_sfarad', '_ashkenaz'), TITLE);
      if (SFARAD) await switchNusach('ספרדי');
    }
    await expectVisibleText(`${TITLE} (${SFARAD ? 'ספרדי' : 'אשכנזי'})`);
    await goToPage(1, TOTAL);

    // 2. «יחיד» → пройти все секции.
    await select('יחיד', 'מניין');
    const individual = await walk();

    // 3. «קודם» до «1 מתוך N», «מניין» → пройти все секции.
    await goToPage(1, TOTAL);
    await select('מניין', 'יחיד');
    const congregation = await walk();

    // Одинаковое число секций; тексты совпадают попарно.
    expect(individual).toHaveLength(TOTAL);
    expect(congregation).toHaveLength(TOTAL);
    for (let i = 0; i < TOTAL; i++) expect(congregation[i]).toBe(individual[i]);

    // Вернуть «יחיד» и נוסח профиля.
    await goToPage(1, TOTAL);
    await select('יחיד', 'מניין');
    if (SFARAD && !hasDeepLinks()) await switchNusach('אשכנזי');
  });
});
